"""Generated bytes/FLV only; reservation, closure, and file commit boundaries."""
import json
import os
from pathlib import Path
import sys

import pytest

ROOT = Path(__file__).resolve().parents[1]
sys.path[:0] = [str(ROOT / "scripts"), str(ROOT)]
from scripts import audio_segments as durable
import stream_recorder as recorder


@pytest.fixture
def day(tmp_path):
    data = tmp_path / "data"
    folder = data / "audio_synthetic_2000-01-01"
    folder.mkdir(parents=True)
    return data, folder


def closed(day, value=b"generated" * 600):
    data, folder = day
    number, path = durable.reserve_segment(data, folder)
    with path.open("xb") as stream:
        stream.write(value)
        stream.flush()
        os.fsync(stream.fileno())
    return durable.publish_closed(data, folder, path, number, 1000, 1002)


def test_reserved_before_creation_and_all_audio_moved_never_reuses_number(day, tmp_path):
    data, folder = day
    number, unused = durable.reserve_segment(data, folder)
    assert number == 1 and not unused.exists()  # Simulated exit before exclusive create.
    record = closed(day)
    assert record["number"] == 2
    archive = tmp_path / "archive"
    archive.mkdir()
    (folder / record["file"]).rename(archive / record["file"])
    assert durable.verify_closed(data, folder, record["file"], require_source=False) == record
    assert durable.reserve_segment(data, folder)[0] == 3


def test_bootstrap_inherits_files_legacy_meta_progress_and_closed_records(day, tmp_path):
    data, folder = day
    (folder / "seg_0002.flv").write_bytes(b"generated")
    (folder / "meta.json").write_text(json.dumps({"segments": [{"file": "seg_0008.flv"}]}))
    (folder / ".transcribed.json").write_text(json.dumps({"seg_0010.flv": {"rows": 1}}))
    record = closed(day)
    assert record["number"] == 11
    # Simulate a previously lost counter, while the closure remains as evidence.
    (folder / durable.INDEX).rename(tmp_path / "counter-retained.json")
    assert durable.reserve_segment(data, folder)[0] == 12


@pytest.mark.parametrize("name,body", [
    (durable.INDEX, '{"broken":'),
    ("meta.json", '{"segments":"bad"}'),
    ("meta.json", '{"segments":[{"file":"../seg_0042.flv"}]}'),
    ("meta.json", '{"segments":[],"sessions":"bad"}'),
    ("meta.json", '{"segments":[{"file":"seg_42.flv"}]}'),
    (".transcribed.json", '{"seg_0042.flv":false}'),
])
def test_uninterpretable_old_state_blocks_unsafe_allocation(day, name, body):
    data, folder = day
    path = folder / name
    path.write_text(body)
    with pytest.raises(durable.SegmentError):
        durable.reserve_segment(data, folder)
    assert path.read_text() == body
    assert not list(folder.glob("seg_*.flv"))


def test_counter_replace_failure_preserves_previous_reservation_and_no_temp(day, monkeypatch):
    data, folder = day
    assert durable.reserve_segment(data, folder)[0] == 1
    original = (folder / durable.INDEX).read_bytes()
    actual_replace = os.replace
    def fail_index(source, destination):
        if Path(destination) == folder / durable.INDEX:
            raise PermissionError("generated counter replace failure")
        return actual_replace(source, destination)
    monkeypatch.setattr(durable.os, "replace", fail_index)
    with pytest.raises(PermissionError):
        durable.reserve_segment(data, folder)
    assert (folder / durable.INDEX).read_bytes() == original
    assert not list(folder.glob("*.tmp"))
    monkeypatch.setattr(durable.os, "replace", actual_replace)
    assert durable.reserve_segment(data, folder)[0] == 2


def tag(kind, data, timestamp=0):
    return (bytes([kind]) + len(data).to_bytes(3, "big") + timestamp.to_bytes(3, "big")
            + b"\0\0\0\0" + data + (11 + len(data)).to_bytes(4, "big"))


SEQUENCE = tag(recorder.TAG_AUDIO, b"\xaf\0\x12\x10")
AUDIO = tag(recorder.TAG_AUDIO, b"\xaf\x01" + b"x" * 12)


def test_real_writer_publishes_only_after_close_and_each_rotation_once(day, monkeypatch):
    data, folder = day
    clock = [1000.0]
    monkeypatch.setattr(recorder, "now", lambda: clock[0])
    writer = recorder.FlvSegWriter(folder, seg_seconds=5)
    writer.begin_connection()
    writer.feed(recorder.FLV_HEADER + SEQUENCE + AUDIO)
    handle = writer.fh
    assert durable.discover(data, folder)[0]["state"] == "source_unconfirmed"
    assert not (folder / "meta.json").exists()
    clock[0] += 6
    writer.feed(AUDIO)
    assert handle.closed
    first = durable.verify_closed(data, folder, "seg_0001.flv")
    assert first["start_ts"] == 1000 and first["end_ts"] == 1006
    assert first["time_source"] == "writer_wall_clock"
    writer.end_connection()
    writer.begin_connection()
    writer.feed(recorder.FLV_HEADER + SEQUENCE + AUDIO)
    writer.close()
    writer.close()
    assert len(writer.segments) == 3 and writer.closure_errors == []
    assert len(list((folder / durable.CLOSED).glob("*.json"))) == 3
    assert all(row["state"] == "closed" for row in durable.discover(data, folder))


def test_exclusive_creation_does_not_overwrite_a_racing_file(day, monkeypatch):
    data, folder = day
    reserve = durable.reserve_segment
    def race(*args):
        number, path = reserve(*args)
        path.write_bytes(b"generated racing writer")
        return number, path
    monkeypatch.setattr(durable, "reserve_segment", race)
    writer = recorder.FlvSegWriter(folder)
    with pytest.raises(FileExistsError):
        writer.feed(recorder.FLV_HEADER + SEQUENCE + AUDIO)
    writer.close()
    assert (folder / "seg_0001.flv").read_bytes() == b"generated racing writer"
    assert writer.segments == []


def test_closure_replace_failure_keeps_audio_handle_closed_and_diagnosis(day, monkeypatch):
    data, folder = day
    messages = []
    writer = recorder.FlvSegWriter(folder, log=messages.append)
    writer.feed(recorder.FLV_HEADER + SEQUENCE + AUDIO)
    handle = writer.fh
    actual_replace = os.replace
    def fail_closed(source, destination):
        if Path(destination).parent.name == durable.CLOSED:
            raise PermissionError("generated closure replace failure")
        return actual_replace(source, destination)
    monkeypatch.setattr(durable.os, "replace", fail_closed)
    writer.close()
    writer.close()
    assert handle.closed and writer.fh is None
    assert len(writer.segments) == len(writer.closure_errors) == 1
    assert writer.segments[0]["closure_state"] == "source_unconfirmed"
    assert messages and (folder / "seg_0001.flv").exists()
    assert durable.discover(data, folder)[0]["state"] == "source_unconfirmed"
    assert not list((folder / durable.CLOSED).glob("*.tmp"))
    recorder.write_meta(folder, {"segments": writer.segments})
    assert json.loads((folder / "meta.json").read_text())["segments"][0]["closure_state"] == "source_unconfirmed"


def test_audio_fsync_failure_closes_handle_without_publishing(day, monkeypatch):
    data, folder = day
    writer = recorder.FlvSegWriter(folder)
    writer.feed(recorder.FLV_HEADER + SEQUENCE + AUDIO)
    handle = writer.fh
    descriptor = handle.fileno()
    actual_fsync = os.fsync
    def fail_audio(fd):
        if fd == descriptor:
            raise PermissionError("generated audio fsync failure")
        return actual_fsync(fd)
    monkeypatch.setattr(recorder.os, "fsync", fail_audio)
    with pytest.raises(PermissionError):
        writer.close()
    writer.close()
    assert handle.closed and writer.fh is None and writer.segments == []
    assert (folder / "seg_0001.flv").exists()
    assert not (folder / durable.CLOSED).exists()


def test_audio_close_failure_is_retried_for_handle_release_without_closure(day):
    _data, folder = day
    writer = recorder.FlvSegWriter(folder)
    writer.feed(recorder.FLV_HEADER + SEQUENCE + AUDIO)
    handle = writer.fh
    class FailFirstClose:
        calls = 0
        def flush(self):
            return handle.flush()
        def fileno(self):
            return handle.fileno()
        def close(self):
            self.calls += 1
            if self.calls == 1:
                raise OSError("generated close failure")
            return handle.close()
    wrapper = writer.fh = FailFirstClose()
    with pytest.raises(OSError, match="generated close failure"):
        writer.close()
    writer.close()
    assert handle.closed and writer.fh is None and wrapper.calls == 2
    assert writer.segments == [] and not (folder / durable.CLOSED).exists()


@pytest.mark.parametrize("field,value", [
    ("schema", True), ("number", True), ("mtime_ns", -1), ("dev", -1),
    ("ino", 0), ("sha256", "not-a-fingerprint"), ("relative", "../seg_0001.flv"),
])
def test_invalid_closed_fields_never_grant_source_trust(day, field, value):
    data, folder = day
    record = closed(day)
    record[field] = value
    durable.atomic_json(folder / durable.CLOSED / "seg_0001.json", record)
    with pytest.raises(durable.SegmentError, match="invalid_closure"):
        durable.verify_closed(data, folder, "seg_0001.flv")


def test_same_size_and_mtime_content_replacement_is_rejected(day):
    data, folder = day
    record = closed(day)
    path = folder / record["file"]
    path.write_bytes(b"z" * record["size"])
    os.utime(path, ns=(record["mtime_ns"], record["mtime_ns"]))
    with pytest.raises(durable.SegmentError, match="source_changed"):
        durable.verify_closed(data, folder, record["file"])


def test_same_bytes_and_time_new_file_identity_is_rejected(day, tmp_path):
    data, folder = day
    record = closed(day)
    path = folder / record["file"]
    raw = path.read_bytes()
    path.rename(tmp_path / "retained-original.flv")
    path.write_bytes(raw)
    os.utime(path, ns=(record["mtime_ns"], record["mtime_ns"]))
    with pytest.raises(durable.SegmentError, match="source_changed"):
        durable.verify_closed(data, folder, record["file"])


def test_outside_data_and_hardlinked_source_are_rejected(day, tmp_path):
    data, folder = day
    outside = tmp_path / "outside"
    outside.mkdir()
    with pytest.raises(durable.SegmentError, match="outside_data"):
        durable.reserve_segment(data, outside)
    record = closed(day)
    os.link(folder / record["file"], outside / "generated-link.flv")
    with pytest.raises(durable.SegmentError, match="invalid_file"):
        durable.verify_closed(data, folder, record["file"])


def test_linked_directory_is_not_followed(day, tmp_path):
    data, _folder = day
    outside = tmp_path / "generated-target"
    outside.mkdir()
    linked = data / "generated-linked-folder"
    try:
        linked.symlink_to(outside, target_is_directory=True)
    except OSError as error:
        pytest.skip("this Windows environment cannot create test symlinks: %s" % error.winerror)
    with pytest.raises(durable.SegmentError, match="linked_path"):
        durable.reserve_segment(data, linked)
    assert list(outside.iterdir()) == []


def test_writer_does_not_create_through_a_linked_parent(day, tmp_path):
    data, _folder = day
    outside = tmp_path / "generated-parent-target"
    outside.mkdir()
    linked = data / "generated-parent-link"
    try:
        linked.symlink_to(outside, target_is_directory=True)
    except OSError as error:
        pytest.skip("this Windows environment cannot create test symlinks: %s" % error.winerror)
    with pytest.raises(durable.SegmentError, match="linked_path"):
        recorder.FlvSegWriter(linked / "must-not-be-created")
    assert list(outside.iterdir()) == []


def test_bad_closure_is_not_discovered_or_used_to_reset_counter(day):
    data, folder = day
    record = closed(day)
    path = folder / durable.CLOSED / "seg_0001.json"
    path.write_text('{"truncated":')
    assert durable.discover(data, folder)[0]["state"] == "source_unconfirmed"
    with pytest.raises(durable.SegmentError):
        durable.reserve_segment(data, folder)
    assert (folder / record["file"]).exists()
